// Codex's own portable apply-patch conformance suite, run against this tool.
//
// `upstream/scenarios/` is a verbatim copy of
// codex-rs/apply-patch/tests/fixtures/scenarios at openai/codex
// a7edf37cb46b5fc4d50bd03df8e5999a86f602eb (Apache-2.0, see ../../NOTICE).
// Upstream's README states its purpose: "meant to be easily portable to other
// languages or platforms". This is the port.
//
// It matters because every other check in this directory was written by whoever
// wrote the code. The oracle fixtures were generated by running the reference
// binary, but over inputs this repository chose; the fuzzer perturbs inputs this
// repository chose how to perturb. These 25 cases were chosen by upstream, before
// and independently of this tool, and are the only inputs here with the standing
// to contradict it.
//
// The comparison is upstream's own: `tests/suite/scenarios.rs` copies `input/`
// to a temporary directory, applies `patch.txt`, deliberately does not assert on
// the exit status, and compares the resulting tree to `expected/` exactly. A
// scenario that must fail is therefore specified by what it left behind, not by
// a message — which is what makes it portable, and what lets it check this tool
// without either side agreeing on error text.

import { strict as assert } from 'node:assert';
import { readdir, readFile, rm } from 'node:fs/promises';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, it } from 'node:test';
import { harness } from './test-harness.mjs';

const SCENARIOS = fileURLToPath(new URL('./upstream/scenarios', import.meta.url));

// Upstream's runner sets CODEX_APPLY_PATCH_PRESERVE_LINE_ENDINGS=1, and the two
// scenarios below are the only ones that can tell. That mode is
// `Stage::UnderDevelopment, default_enabled: false` in the feature registry
// (features/src/lib.rs:1005-1009), so a shipped Codex — and therefore this arm —
// runs `ApplyPatchFileUpdateMode::NormalizeToLf`, its `#[default]`. The expected
// bytes here are that default's, and the divergence is the flag, not the applier.
//
// 015 is the other axis: it specifies the standalone binary, which applies
// operations one at a time with no verification pass, so an add that precedes a
// failing update survives. The function tool a model calls verifies the whole
// envelope first (invocation.rs:214) and writes nothing. This tool implements
// the function tool; the same divergence is recorded for two oracle fixtures in
// codex-fixtures.test.mjs.
const DIVERGENCES = new Map([
  [
    '015_failure_after_partial_success_leaves_changes',
    {
      why: 'verification refuses the envelope before the add is written; upstream specifies the unverified binary',
      tree: {},
    },
  ],
  [
    '023_preserves_crlf_line_endings',
    {
      why: 'specified under the preserve-line-endings feature, which ships disabled',
      tree: { 'lines.txt': 'ONE\ntwo\nbetween\nthree\n' },
    },
  ],
  [
    '024_preserves_mixed_line_endings',
    {
      // The input carries a bare CR as one of its line endings. Splitting on LF
      // alone makes `two\rthree` a single line, so `-three` is not there to be
      // found and the patch is refused with the file untouched. The reference
      // binary run without the flag does the same, byte for byte.
      why: 'specified under the preserve-line-endings feature, which ships disabled',
      tree: { 'lines.txt': 'one\r\ntwo\rthree\nfour\r\n' },
    },
  ],
]);

async function readTree(root) {
  const files = {};
  const walk = async (dir) => {
    for (const entry of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) await walk(path);
      else files[relative(root, path)] = await readFile(path, 'utf8');
    }
  };
  await walk(root);
  return files;
}

const scenarios = (await readdir(SCENARIOS, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)
  .sort();

describe('codex apply-patch scenarios', () => {
  // A miscopied or half-copied fixture tree would silently shrink this suite to
  // whatever survived, and every remaining case would still pass.
  it('has the whole upstream scenario set', () => {
    assert.equal(scenarios.length, 25);
  });

  for (const name of scenarios) {
    const divergence = DIVERGENCES.get(name);
    it(divergence === undefined ? name : `${name} — ${divergence.why}`, async () => {
      const dir = join(SCENARIOS, name);
      const files = await readTree(join(dir, 'input'));
      const patch = await readFile(join(dir, 'patch.txt'), 'utf8');
      const expected = divergence?.tree ?? (await readTree(join(dir, 'expected')));

      const { run, tree, root } = await harness({ files });
      try {
        // Upstream ignores the exit status and specifies the scenario purely as
        // final state, so a refusal is a legitimate outcome and is compared the
        // same way a success is.
        await run(patch).catch(() => undefined);
        assert.deepEqual(await tree(), expected);
      } finally {
        await rm(root, { recursive: true, force: true });
      }
    });
  }

  it('lists no divergence that has stopped diverging', async () => {
    for (const [name, divergence] of DIVERGENCES) {
      assert.ok(scenarios.includes(name), `divergence "${name}" names no scenario`);
      assert.notDeepEqual(
        await readTree(join(SCENARIOS, name, 'expected')),
        divergence.tree,
        `divergence "${name}" now matches upstream — delete the entry`,
      );
    }
  });
});
